import 'dart:io';
import 'package:drift/drift.dart';
import 'package:drift/native.dart';
import 'package:path_provider/path_provider.dart';
import 'package:path/path.dart' as p;

import 'tables.dart';

// This file is generated by running build_runner
part 'database.g.dart';

@DriftDatabase(tables: [
  Products,
  Customers,
  Suppliers,
  Sales,
  SaleItems,
  AppSettings,
  Transactions,
])
class AppDatabase extends _$AppDatabase {
  AppDatabase() : super(_openConnection());

  @override
  int get schemaVersion => 1;

  // ============ INVENTORY QUERIES ============
  Future<List<Product>> getAllProducts() => select(products).get();
  Future<int> insertProduct(ProductsCompanion product) => into(products).insert(product);
  Future<bool> updateProduct(Product product) => update(products).replace(product);
  Future<int> deleteProduct(int id) => (delete(products)..where((t) => t.id.equals(id))).go();

  // ============ CUSTOMER QUERIES ============
  Future<List<Customer>> getAllCustomers() => select(customers).get();
  Future<int> insertCustomer(CustomersCompanion customer) => into(customers).insert(customer);
  Future<bool> updateCustomer(Customer customer) => update(customers).replace(customer);
  Future<int> deleteCustomer(int id) => (delete(customers)..where((t) => t.id.equals(id))).go();

  // ============ SETTINGS QUERIES ============
  // Default we deal with 1 setting row for company config
  Future<AppSetting?> getSettings() {
    return select(appSettings).getSingleOrNull();
  }
  Future<void> saveSettings(AppSettingsCompanion settings) async {
    final existing = await getSettings();
    if (existing == null) {
      await into(appSettings).insert(settings);
    } else {
      await update(appSettings).replace(
        settings.copyWith(id: Value(existing.id))
      );
    }
  }
}

LazyDatabase _openConnection() {
  return LazyDatabase(() async {
    final dbFolder = await getApplicationDocumentsDirectory();
    final bkFolder = Directory(p.join(dbFolder.path, 'BK_ERP'));
    
    if (!await bkFolder.exists()) {
      await bkFolder.create(recursive: true);
    }
    
    final file = File(p.join(bkFolder.path, 'bk_erp_database.sqlite'));
    return NativeDatabase.createInBackground(file);
  });
}
